'use client';

import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Github, Linkedin, FileText } from 'lucide-react';
import { useSectionInView } from '@/hooks/use-section-in-view';
import { PERSONAL_INFO, PERSONAL_INFO_LINKS } from '@/data/personal-info';
import heroBg from '@/assets/hero-bg.jpg';
import { getResumeDownloadLink } from '@/lib/utils';
import { fadeInUp, scaleIn, staggerContainer, viewport } from '@/lib/motion';

const scrollToSection = (href: string) => {
  const element = document.querySelector(href);
  if (element) {
    element.scrollIntoView({ behavior: 'smooth' });
  }
};

export function HeroSection() {
  const { ref } = useSectionInView('Home', 0.5);

  const stats = [
    { label: 'Years Experience', value: '1+' },
    { label: 'Projects Completed', value: '6+' },
    { label: 'Technologies Mastered', value: '10+' },
  ];

  const downloadResume = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    
    try {
      const downloadLink = getResumeDownloadLink();
      const response = await fetch('/jenil-gajera-resume.pdf');
      
      if (!response.ok) {
        // Try alternative path
        const altResponse = await fetch('/resume.pdf');
        if (!altResponse.ok) {
          throw new Error('Resume file not found');
        }
        const blob = await altResponse.blob();
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = downloadLink;
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        setTimeout(() => {
          document.body.removeChild(link);
          window.URL.revokeObjectURL(url);
        }, 100);
        return;
      }
      
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = downloadLink;
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      setTimeout(() => {
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      }, 100);
    } catch (error) {
      console.error('Error downloading resume:', error);
      alert('Resume file not found. Please ensure the PDF exists in the public folder.');
    }
  };

  return (
    <div ref={ref} id="home" className="min-h-screen bg-gradient-bg">
      <section className="min-h-screen relative flex items-center justify-center overflow-hidden">
        {/* Background */}
        <motion.div
          initial={{ opacity: 0, scale: 1.08 }}
          whileInView={{ opacity: 1, scale: 1 }}
          viewport={viewport}
          transition={{ duration: 0.9, ease: 'easeOut' }}
          className="absolute inset-0 bg-cover bg-center bg-no-repeat opacity-20 dark:opacity-10"
          style={{ backgroundImage: `url(${heroBg.src})` }}
        />

        {/* Content */}
        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <motion.div
            variants={staggerContainer}
            initial="hidden"
            whileInView="show"
            viewport={viewport}
            className="space-y-8"
          >
            {/* Name & Title */}
            <motion.div variants={fadeInUp} transition={{ duration: 0.55 }} className="space-y-4">
              <motion.h1
                variants={scaleIn}
                transition={{ duration: 0.6, ease: 'easeOut' }}
                className="text-5xl md:text-7xl font-bold bg-gradient-to-r from-primary via-accent to-primary bg-clip-text text-transparent"
              >
                {PERSONAL_INFO.fullName}
              </motion.h1>
              <p className="text-xl md:text-2xl text-muted-foreground font-medium">
                {PERSONAL_INFO.designation}
              </p>
              <p className="text-lg text-muted-foreground max-w-2xl mx-auto leading-relaxed">
                Crafting innovative web solutions with MongoDB, Express.js, React, and Node.js. Passionate about
                clean code and exceptional user experiences.
              </p>
            </motion.div>

            {/* CTA Buttons */}
            <motion.div variants={fadeInUp} transition={{ duration: 0.55 }} className="flex flex-col sm:flex-row gap-4 justify-center items-center">
              <motion.div whileHover={{ y: -3 }} whileTap={{ scale: 0.98 }}>
                <Button size="lg" onClick={downloadResume}>
                  <FileText className="mr-2 h-5 w-5" /> Download Resume
                </Button>
              </motion.div>
              <motion.div whileHover={{ y: -3 }} whileTap={{ scale: 0.98 }}>
                <Button variant="outline" size="lg" onClick={() => scrollToSection('#contact')}>
                  Contact Me
                </Button>
              </motion.div>
            </motion.div>

            {/* Social Links */}
            <motion.div variants={fadeInUp} transition={{ duration: 0.55 }} className="flex justify-center space-x-6">
              <motion.a
                whileHover={{ y: -4, scale: 1.08 }}
                whileTap={{ scale: 0.96 }}
                href={PERSONAL_INFO_LINKS.github}
                target="_blank"
                rel="noopener noreferrer"
                className="text-muted-foreground hover:text-primary transition-colors duration-200"
              >
                <Github className="h-6 w-6" />
              </motion.a>
              <motion.a
                whileHover={{ y: -4, scale: 1.08 }}
                whileTap={{ scale: 0.96 }}
                href={PERSONAL_INFO_LINKS.linkedIn}
                target="_blank"
                rel="noopener noreferrer"
                className="text-muted-foreground hover:text-primary transition-colors duration-200"
              >
                <Linkedin className="h-6 w-6" />
              </motion.a>
            </motion.div>
          </motion.div>
        </div>

        {/* Quick Stats */}
        <div className="absolute bottom-0 left-0 right-0 bg-background/80 backdrop-blur-sm border-t">
          <motion.div
            initial={{ opacity: 0, y: 28 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={viewport}
            transition={{ duration: 0.55, ease: 'easeOut' }}
            className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6"
          >
            <div className="grid grid-cols-3 gap-8 text-center">
              {stats.map((stat, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={viewport}
                  transition={{ duration: 0.5, delay: index * 0.1 }}
                  whileHover={{ y: -5 }}
                  className="space-y-2"
                >
                  <div className="text-2xl md:text-3xl font-bold text-primary">{stat.value}</div>
                  <div className="text-sm text-muted-foreground">{stat.label}</div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </div>
      </section>
    </div>
  );
}
